const fim = new Date();
const inicio = new Date(fim.getTime() - 24 * 60 * 60 * 1000);
const iso = d => d.toISOString();
const nvd = new URL('https://services.nvd.nist.gov/rest/json/cves/2.0');
nvd.searchParams.set('pubStartDate', iso(inicio));
nvd.searchParams.set('pubEndDate', iso(fim));
nvd.searchParams.set('resultsPerPage', '2000');
return [{ json: {
  inicio: iso(inicio),
  fim: iso(fim),
  inicioData: iso(inicio).slice(0, 10),
  fimData: iso(fim).slice(0, 10),
  nvdUrl: nvd.toString(),
  ransomwareUrl: 'https://api-pro.ransomware.live/victims/recent',
  cisaUrl: 'https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json',
  timezone: 'America/Sao_Paulo'
} }];

const root = $input.first()?.json ?? {};
const rows = Array.isArray(root.vulnerabilities) ? root.vulnerabilities : [];
const getMetric = cve => {
  const m = cve.metrics || {};
  // Mantém CVSS v2 em "Sem CVSSv3", conforme a classificação solicitada.
  const candidates = [m.cvssMetricV40?.[0], m.cvssMetricV31?.[0], m.cvssMetricV30?.[0]].filter(Boolean);
  const d = candidates[0]?.cvssData || {};
  return { score: Number(d.baseScore || 0), severity: String(d.baseSeverity || candidates[0]?.baseSeverity || 'SEM CVSSV3').toUpperCase() };
};
const text = cve => (cve.descriptions || []).find(d => d.lang === 'en')?.value || (cve.descriptions || [])[0]?.value || 'Sem resumo disponível';
const counts = { CRITICAL: 0, HIGH: 0, MEDIUM: 0, LOW: 0, 'SEM CVSSV3': 0 };
const cves = rows.map(v => {
  const cve = v.cve || {};
  const metric = getMetric(cve);
  const severity = counts[metric.severity] === undefined ? 'SEM CVSSV3' : metric.severity;
  counts[severity]++;
  return { id: cve.id || 'N/A', ...metric, severity, resumo: text(cve), publicada: cve.published, url: `https://nvd.nist.gov/vuln/detail/${cve.id}` };
});
const themes = [
  ['RCE', /remote code execution|arbitrary code execution|execute arbitrary code/i],
  ['Authentication bypass', /authentication bypass|bypass authentication|unauthenticated/i],
  ['SQL Injection', /sql injection/i],
  ['Path traversal', /path traversal|directory traversal/i],
  ['Elevação de privilégios', /privilege escalation|elevation of privilege/i],
  ['Takeover', /takeover/i]
].filter(([, re]) => cves.some(c => ['CRITICAL', 'HIGH'].includes(c.severity) && re.test(c.resumo))).map(([name]) => name);
return [{ json: { nvd: {
  ok: !root.error,
  erro: root.error?.message || root.error || null,
  total: cves.length,
  contagem: counts,
  temas: themes,
  destaques: cves.filter(c => c.severity === 'CRITICAL').sort((a, b) => b.score - a.score).slice(0, 12)
} } }];

const root = $input.first()?.json ?? {};
const inicioData = $('Definir janela de 24 horas').first().json.inicioData;
const fimData = $('Definir janela de 24 horas').first().json.fimData;
const all = Array.isArray(root.vulnerabilities) ? root.vulnerabilities : [];
// O feed KEV só informa a data (não a hora); por isso a seleção é por datas que interceptam a janela.
const novas = all.filter(v => v.dateAdded >= inicioData && v.dateAdded <= fimData).map(v => ({
  cve: v.cveID,
  fornecedor: v.vendorProject,
  produto: v.product,
  nome: v.vulnerabilityName,
  adicionadoEm: v.dateAdded,
  prazo: v.dueDate,
  ransomware: v.knownRansomwareCampaignUse
}));
return [{ json: { cisa: { ok: !root.error, erro: root.error?.message || root.error || null, novas } } }];

const root = $input.first()?.json ?? {};
const start = new Date($('Definir janela de 24 horas').first().json.inicio).getTime();
const end = new Date($('Definir janela de 24 horas').first().json.fim).getTime();
const list = Array.isArray(root) ? root : (root.data || root.victims || root.results || []);
const victims = (Array.isArray(list) ? list : []).map(v => ({
  nome: v.victim || v.post_title || v.title || v.name || 'N/A',
  grupo: v.group || v.group_name || v.ransomware_group || 'N/A',
  pais: String(v.country || v.country_code || 'N/A').toUpperCase(),
  setor: v.activity || v.sector || v.industry || 'N/A',
  descobertoEm: v.discovered || v.discovered_at || v.created_at || v.date,
  dominio: v.website || v.domain || '',
  url: v.permalink || v.claim_url || v.url || ''
})).filter(v => {
  const t = new Date(v.descobertoEm).getTime();
  return Number.isFinite(t) && t >= start && t <= end;
});
const countBy = key => Object.entries(victims.reduce((a, v) => { const k = v[key] || 'N/A'; a[k] = (a[k] || 0) + 1; return a; }, {})).sort((a, b) => b[1] - a[1]);
return [{ json: { ransomware: {
  ok: !root.error,
  erro: root.error?.message || root.error || null,
  total: victims.length,
  brasil: victims.filter(v => v.pais === 'BR').length,
  porGrupo: countBy('grupo'),
  porPais: countBy('pais'),
  porSetor: countBy('setor'),
  vitimas: victims
} } }];

const root = $input.first()?.json ?? {};
const list = Array.isArray(root) ? root : (root.clients || root.data || root.results || root.items || []);
const clientes = (Array.isArray(list) ? list : []).map(c => ({
  nome: c.name || c.nome || c.company_name || c.organization || '',
  dominios: [c.domain, c.dominio, ...(Array.isArray(c.domains) ? c.domains : []), ...(Array.isArray(c.dominios) ? c.dominios : [])].filter(Boolean),
  aliases: [c.alias, ...(Array.isArray(c.aliases) ? c.aliases : [])].filter(Boolean),
  setor: c.sector || c.setor || c.industry || ''
})).filter(c => c.nome || c.dominios.length);
return [{ json: { recon5: { configurada: true, ok: !root.error, erro: root.error?.message || root.error || null, clientes } } }];

const start = new Date($('Definir janela de 24 horas').first().json.inicio).getTime();
const end = new Date($('Definir janela de 24 horas').first().json.fim).getTime();
const strip = s => String(s || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const seen = new Set();
const noticias = $input.all().map(i => i.json).map(n => ({
  titulo: strip(n.title),
  link: n.link || n.guid || '',
  publicadaEm: n.isoDate || n.pubDate || n.pubdate || n.date,
  resumo: strip(n.contentSnippet || n.content || n.description).slice(0, 280),
  fonte: String(n.link || '').includes('bleepingcomputer') ? 'BleepingComputer' : 'The Hacker News'
})).filter(n => {
  const t = new Date(n.publicadaEm).getTime();
  const key = n.link || n.titulo.toLowerCase();
  if (!n.titulo || seen.has(key) || !Number.isFinite(t) || t < start || t > end) return false;
  seen.add(key);
  return true;
}).sort((a, b) => new Date(b.publicadaEm) - new Date(a.publicadaEm)).slice(0, 8);
return [{ json: { noticias: { total: noticias.length, itens: noticias } } }];

const d = $input.first().json;
const ransomware = d.ransomware || { total: 0, brasil: 0, porGrupo: [], porPais: [], porSetor: [], vitimas: [], ok: false };
const cisa = d.cisa || { novas: [], ok: false };
const nvd = d.nvd || { total: 0, contagem: {}, temas: [], destaques: [], ok: false };
const recon = d.recon5 || { configurada: false, clientes: [] };
const news = d.noticias || { itens: [] };
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/^www\./, '').replace(/[^a-z0-9.-]+/g, ' ').trim();
const tokens = c => [c.nome, ...(c.aliases || []), ...(c.dominios || [])].map(norm).filter(x => x.length >= 4);
const matches = [];
for (const v of ransomware.vitimas || []) {
  const haystack = norm(`${v.nome} ${v.dominio}`);
  for (const c of recon.clientes || []) {
    const hit = tokens(c).find(t => haystack === t || haystack.includes(t) || t.includes(haystack));
    if (hit) matches.push({ cliente: c.nome, vitima: v.nome, grupo: v.grupo, termo: hit });
  }
}
const setoresEnv = String($env.NGSOC_SETORES || '').split(',').map(norm).filter(Boolean);
const setoresClientes = (recon.clientes || []).map(c => norm(c.setor)).filter(Boolean);
const setores = [...new Set([...setoresEnv, ...setoresClientes])];
const correlatos = (ransomware.vitimas || []).filter(v => { const s = norm(v.setor); return setores.some(x => x.length >= 4 && (s.includes(x) || x.includes(s))); });
const top = (rows, max = 12) => rows.slice(0, max).map(([k, v]) => `${k}: ${v}`).join(' · ') || 'nenhum';
const statusRecon = !recon.configurada ? 'A correlação nominal com a Recon5 não foi executada porque a integração não está configurada.' : matches.length ? `${matches.length} correspondência(s) potencial(is) com clientes NGSOC exigem validação humana: ${matches.map(m => `${m.cliente} ↔ ${m.vitima} (${m.grupo})`).join('; ')}.` : 'Nenhum cliente NGSOC aparece como correspondência nominal nas divulgações coletadas (cruzamento automatizado com a base Recon5).';
const cveLines = (nvd.destaques || []).map(c => `- [${c.id}](${c.url}) | ${c.score || 'N/A'} | ${c.resumo.slice(0, 180)}`).join('\n') || '- Nenhum CVE Critical publicado na janela.';
const kevLines = (cisa.novas || []).map(v => `- ${v.cve} — ${v.fornecedor} ${v.produto}: ${v.nome}`).join('\n') || '- Não houve adições identificadas no catálogo CISA KEV na janela.';
const newsLines = (news.itens || []).map(n => `- [${n.titulo}](${n.link}) — ${n.fonte}`).join('\n') || '- Nenhuma notícia nova foi obtida dos feeds na janela.';
const br = ransomware.brasil === 0 ? 'Nenhuma vítima com país BR no período.' : `${ransomware.brasil} vítima(s) com país BR no período.`;
const mensagem = `Bom dia, pessoal!\n\nNas últimas 24 horas, ${statusRecon} Foram observadas **${ransomware.total}** novas alegações em leak sites; ${br}${correlatos.length ? ` Há ${correlatos.length} ocorrência(s) em setores correlatos aos segmentos configurados.` : ''}\n\nO monitoramento contemplou possíveis vazamentos, menções a clientes e setores, vulnerabilidades publicadas, exploração ativa conhecida, novas alegações de ransomware e notícias relevantes. Alegações de leak sites são inteligência não confirmada e devem ser corroboradas antes de tratamento como incidente.\n\n## 1. Ransomware\n- Novas vítimas: **${ransomware.total}**\n- Brasil: **${ransomware.brasil}**\n- Grupos: ${top(ransomware.porGrupo || [])}\n- Países: ${top(ransomware.porPais || [])}\n- Setores: ${top(ransomware.porSetor || [])}\n\n## 2. CISA KEV\n${kevLines}\n\n## 3. CVEs NVD (publicados na janela)\n- Total: **${nvd.total}**\n- Critical: **${nvd.contagem?.CRITICAL || 0}** | High: **${nvd.contagem?.HIGH || 0}** | Medium: **${nvd.contagem?.MEDIUM || 0}** | Low: **${nvd.contagem?.LOW || 0}** | Sem CVSS: **${nvd.contagem?.['SEM CVSSV3'] || 0}**\n- Temas Critical + High: ${(nvd.temas || []).join(' · ') || 'nenhum tema-chave identificado'}\n\n### Critical — destaques\n${cveLines}\n\n## 4. Principais notícias de cibersegurança\n${newsLines}\n\nSeguimos com o monitoramento contínuo e informaremos prontamente caso sejam identificados eventos que demandem atenção.\n\n_Fontes: NVD/NIST, CISA KEV, ransomware.live PRO, The Hacker News e BleepingComputer. Janela UTC: ${$('Definir janela de 24 horas').first().json.inicio} a ${$('Definir janela de 24 horas').first().json.fim}._`;
const safe = mensagem.slice(0, 24500);
return [{ json: {
  mensagemMarkdown: safe,
  requerAtencao: matches.length > 0 || (cisa.novas || []).length > 0 || (nvd.destaques || []).length > 0,
  teamsPayload: {
    type: 'message',
    attachments: [{
      contentType: 'application/vnd.microsoft.card.adaptive',
      contentUrl: null,
      content: {
        '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json',
        type: 'AdaptiveCard',
        version: '1.4',
        body: [
          { type: 'TextBlock', size: 'Large', weight: 'Bolder', text: 'Boletim diário NGSOC — Cyber Threat Intelligence', wrap: true },
          { type: 'TextBlock', text: safe, wrap: true }
        ]
      }
    }]
  }
} }];
